'use strict';
const API_BASE = location.protocol === 'file:' ? 'http://127.0.0.1:8787' : '';
const $=id=>document.getElementById(id),money=value=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(value);
function link(element,url){try{if(new URL(url).origin!=='https://www.carwale.com')throw Error();element.href=url;element.hidden=false;}catch{element.hidden=true;}}
function list(id,items){const target=$(id);target.replaceChildren();if(!items.length){const p=document.createElement('p');p.className='section-copy';p.textContent='No verified specification data was returned.';target.append(p);return;}for(const item of items){const row=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=item.name;dd.textContent=`${item.value}${item.unit?' '+item.unit:''}`;row.append(dt,dd);target.append(row);}}
function render(report){const vehicle=report.vehicle,valuation=report.valuation,features=report.features;$('report-title').textContent=`${vehicle.make} ${vehicle.model}`;const variantDetail=[vehicle.variant,vehicle.generation,[vehicle.fuel,vehicle.transmission].filter(Boolean).join(' ')].filter(Boolean).join(' · ');$('report-variant').textContent=variantDetail||'Year-specific variant data unavailable';document.title=`${vehicle.make} ${vehicle.model} valuation — CarValue`;$('report-date').textContent=`Created ${new Date(report.createdAt).toLocaleString('en-IN')}`;for(const text of [`${vehicle.year}`,`${vehicle.distanceKm.toLocaleString('en-IN')} km`,`${vehicle.owners}${vehicle.owners===3?'+':''} owner${vehicle.owners===1?'':'s'}`,vehicle.city].filter(Boolean)){const span=document.createElement('span');span.textContent=text;$('report-chips').append(span);}
 const estimated=valuation.status==='estimated';$('report-badge').textContent=estimated?'MARKET COMPARISON':'MORE EVIDENCE NEEDED';$('report-price').textContent=estimated?money(valuation.estimatedPrice):'Estimate unavailable';$('report-price').classList.toggle('price-unavailable',!estimated);$('report-reason').textContent=valuation.reason||'';$('report-range').textContent=valuation.range?`${money(valuation.range.low)} – ${money(valuation.range.high)}`:'Not enough data';$('range-caption').textContent=valuation.range?.label||'No fixed fallback or generic base price is used.';$('used-count').textContent=String(valuation.used||0);$('scanned-count').textContent=String(valuation.scanned||0);
 const highlights=$('feature-highlights');for(const item of features.highlights||[]){const card=document.createElement('article'),name=document.createElement('h3'),value=document.createElement('strong'),note=document.createElement('p');name.textContent=item.name;value.textContent=item.value;note.textContent=(item.comparedWith||[]).map(p=>`${p.variant}: ${p.value}`).join(' · ');card.append(name,value,note);highlights.append(card);}if(!highlights.children.length){const p=document.createElement('p');p.className='section-copy';p.textContent=features.equipment?.length?'Equipment is available below, but no documented differences were established against the other retrieved variants.':'No year-matched equipment data is available. Features have not been inferred from the brand.';highlights.append(p);}$('feature-note').textContent=features.coverage||'';list('equipment-list',features.equipment||[]);list('technical-list',features.specifications||[]);link($('spec-source'),features.source);$('spec-timestamp').textContent=features.fetchedAt?`Specifications retrieved ${new Date(features.fetchedAt).toLocaleString('en-IN')}. Values come from the source’s selected production-period record.`:'';
 const rows=valuation.evidence||[];$('no-evidence').hidden=!!rows.length;$('evidence-wrap').hidden=!rows.length;for(const row of rows){const tr=document.createElement('tr');const title=document.createElement('td'),a=document.createElement('a');a.textContent=row.title.split('(Second')[0].split('(second')[0].trim()||`${row.make} ${row.model}`;a.target='_blank';a.rel='noopener noreferrer';link(a,row.url);title.append(a);tr.append(title);for(const value of [row.year,`${row.distanceKm.toLocaleString('en-IN')} km`,row.city||'Not recorded',money(row.price),row.sameTrim?'Matching trim':'Same generation']){const td=document.createElement('td');td.textContent=String(value);tr.append(td);}$('evidence-body').append(tr);}link($('market-source'),valuation.source);$('comparison-scope').textContent=valuation.scope==='same_variant'?'The closest matching-trim listings are shown. Advertised prices can differ from completed sale prices.':'These comparisons may include other trims. Exact variant-specific price effects are not established.';$('report-method').textContent=report.methodology;$('report-rules').textContent=valuation.comparableRules||'A valuation is withheld when matching specifications or enough comparable listings are unavailable.';$('report-loading').hidden=true;$('report-content').hidden=false;}
(async()=>{try{const id=new URLSearchParams(location.search).get('id');if(!id)throw Error('Select a vehicle and create a valuation first.');const response=await fetch(`${API_BASE}/api/valuations/${encodeURIComponent(id)}`);const report=await response.json();if(!response.ok)throw Error(report.error||'This report could not be loaded.');render(report);
 // ML estimate — runs in parallel, non-blocking
 const v=report.vehicle;
 fetch(`${API_BASE}/api/ml-predict`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({make:v.make,year:v.year,km:v.distanceKm,fuel:v.fuel||'Petrol',transmission:v.transmission||'Manual',owners:v.owners})})
  .then(r=>r.json()).then(ml=>{if(ml.price){$('ml-price').textContent=money(ml.price);$('ml-reason').textContent=`Confidence: ${ml.confidence} · Based on brand, age, mileage, fuel and transmission`;$('ml-section').hidden=false;}}).catch(()=>{});
}catch(error){$('report-loading').hidden=true;$('report-error').textContent=error.message;$('report-error').hidden=false;}})();
